n.exploreUrl:
@js:
  sort = [];
  push = (title, url, type) =>  
    sort.push({
      title: title,
      url: url,
      style: {
          layout_flexGrow: 1,
          layout_flexBasisPercent: type
       }
     });
     push("༺ˇ»`ʚ最近更新ɞ´«ˇ༻", "", "1")
  url = source.getKey();
  o = org.jsoup.Jsoup.parse(java.ajax(url));
  s = o.select('ul[class="nav"] a');
  for(i in s){
    if(i >= 3 && i <= 8){
      u = String(s[i].attr("href")).replace(/\d+\.html/,"{{page}}.html");
        push(s[i].text(), u, "0.25")
      }else if(i > 8 && i != 12){
      	t = s[i].text()
      	t1 = "༺ˇ»`ʚ" + t + "ɞ´«ˇ༻";
      	push(t1,s[i].attr("href"),"1")
      	}
   };
 JSON.stringify(sort);

